INSERT INTO submissions (cat, q, a, fq, fa, difficulty, status, source) VALUES
  ('HTML', 'What does the `<!DOCTYPE html>` declaration do?', 'Tells the browser to render in **standards mode** instead of **quirks mode** (which emulates legacy, non-standard behavior). `<!DOCTYPE html>` is the HTML5 doctype. It''s not a tag — it''s an instruction to the parser.', 'What actually breaks in quirks mode?', 'The classic one is the box model — widths start including padding/border (like `border-box`), so layouts shift. Various other legacy CSS quirks and inconsistent defaults also kick in.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Difference between block, inline, and inline-block elements?', '- **Block** (`div`, `p`): starts on a new line, takes full width, respects `width`/`height` and vertical margins.
- **Inline** (`span`, `a`): flows within text, only as wide as its content, ignores `width`/`height` and vertical margins.
- **Inline-block**: flows inline but respects `width`, `height`, and all margins — a hybrid.', 'Why does setting a height on an inline element do nothing?', 'Inline boxes are sized by the line/content flow, so `width` and `height` simply don''t apply. Switch to `inline-block` or `block` if you need dimensions.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What are semantic HTML elements and why use them?', 'Elements that describe their **meaning** (`header`, `nav`, `main`, `article`, `section`, `footer`) rather than just appearance (`div`, `span`). Benefits: accessibility (screen readers understand structure), SEO, and more readable, maintainable code.', 'Do semantic tags improve SEO directly, or only accessibility?', 'Both, but the SEO benefit is indirect — engines use structure to understand hierarchy. The guaranteed win is accessibility and maintainability.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What''s the difference between `<div>` and `<span>`?', 'Both are generic containers with no semantic meaning. `div` is **block-level** (layout chunks); `span` is **inline** (styling/targeting text within a line).', 'Is it valid to put a `<div>` inside a `<p>`?', 'No — a `p` can only contain phrasing (inline) content. The browser auto-closes the `p` before the `div`, which often surprises people debugging broken layouts.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Why is the `alt` attribute on images important?', 'It''s a text alternative: read by screen readers, shown if the image fails to load, and helps SEO.', 'What `alt` text should a purely decorative image have?', 'Empty: `alt=""`. That tells screen readers to skip it. Omitting `alt` entirely is worse — some readers announce the file name instead.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What''s the difference between `id` and `class`?', '- `id` is **unique** (one per page), targets a single element.
- `class` is **reusable** across many elements.
- In specificity, `id` (100) beats `class` (10).', 'Can an element have multiple classes and multiple ids?', 'Multiple classes: yes (space-separated). Multiple ids: no — an id must be unique per page, and each element has at most one.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What are `data-*` attributes?', 'Custom attributes to store extra data on an element without misusing standard ones, e.g. `<div data-user-id="42">`.', 'How do you read `data-user-id` in JS via `dataset`?', '`element.dataset.userId` — the `data-` prefix is dropped and hyphenated segments become camelCase.', 'intermediate', 'approved', 'core'),
  ('HTML', '`<strong>`/`<b>` and `<em>`/`<i>` — what''s the difference?', 'They look the same, but semantically `strong`/`em` carry **meaning** (importance/emphasis) and are announced by screen readers, while `b`/`i` are **purely visual**.', 'If they look identical, why does the distinction matter?', 'Screen readers can convey emphasis/importance for `em`/`strong`; `b`/`i` carry none. It also communicates intent to other developers.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Difference between `<section>`, `<article>`, and `<div>`?', '- `article`: self-contained, independently distributable content (post, comment, product card).
- `section`: a thematic grouping, usually with a heading.
- `div`: no meaning — a styling/layout hook only.', 'Should every `<section>` have a heading?', 'Ideally yes — a section is a thematic grouping and usually warrants a heading for the document outline. If there''s no natural heading, a `div` may fit better.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What is the DOM?', 'The **Document Object Model** — the browser''s live, in-memory tree representing the page. Each element, attribute, and text becomes a node. JS reads and mutates this tree; it''s the API between HTML and JS.', 'Is the DOM the same as your HTML source?', 'No. The DOM is parsed, possibly error-corrected, and reflects JS changes at runtime. The HTML is just the initial input.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Difference between `<script>`, `<script async>`, and `<script defer>`?', '- **plain**: HTML parsing pauses while the script downloads and runs (blocking).
- **async**: downloads in parallel, runs as soon as ready; order not guaranteed.
- **defer**: downloads in parallel, runs after parsing finishes, in document order.', 'Which should you use for a script that manipulates the DOM?', '`defer` — it runs after parsing completes (DOM ready) and preserves order. `async` might run before the DOM exists.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What are void (self-closing) elements?', 'Elements with no content and no closing tag: `img`, `br`, `hr`, `input`, `meta`, `link`.', 'Is the self-closing slash `<br />` required in HTML5?', 'No — it''s optional and ignored by the HTML parser. It only matters in XML/XHTML. In JSX, though, it IS required.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What goes in the `<head>`?', 'Metadata that isn''t rendered directly: `title`, `meta` tags (charset, viewport, description), `link` (stylesheets/favicons), and script references.', 'Why can a large `<script>` at the top of `<head>` hurt performance?', 'A blocking script there stalls HTML parsing and delays rendering. Use `defer`/`async` or move scripts to the end of `<body>`.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What does the viewport meta tag do?', '```html
<meta name="viewport" content="width=device-width, initial-scale=1.0">
```
It matches the layout width to the device width and sets initial zoom, so responsive design works on mobile.', 'What happens on mobile if you omit it?', 'The browser assumes a ~980px desktop width and zooms out, so your `min-width` media queries never trigger and text looks tiny.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Difference between GET and POST in forms?', '- **GET**: data in the URL, visible/bookmarkable, size-limited, for retrieving data.
- **POST**: data in the request body, not shown in URL, no practical size limit, for submitting/changing data.', 'Why shouldn''t you use GET for a login form?', 'GET puts data in the URL, so credentials would land in history, server logs, and referrer headers. POST keeps them in the body.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Name some HTML5 input types and their value.', '`email`, `number`, `tel`, `url`, `date`, `time`, `range`, `color`, `search`. They give built-in validation, the right mobile keyboard, and native UI (date pickers, sliders) for free.', 'Does `type="email"` guarantee a valid email server-side?', 'No — client validation is a UX convenience and trivially bypassed. Always validate on the server too.', 'intermediate', 'approved', 'core'),
  ('HTML', 'localStorage vs sessionStorage vs cookies?', '- **localStorage**: ~5–10MB, persists until cleared, not sent to server.
- **sessionStorage**: same API, cleared when the tab closes.
- **cookies**: ~4KB, sent with every HTTP request, can expire, used for auth/sessions.', 'Which is sent to the server on every request, and why does that matter?', 'Cookies. That''s why they suit auth/sessions but should stay small — they add overhead to every request. Local/session storage never leave the browser.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What is web accessibility (a11y) and what is ARIA?', 'Building sites usable by people with disabilities. **ARIA** attributes (`aria-label`, `role`, `aria-hidden`) add semantics for assistive tech when native HTML can''t. Rule: use native semantic HTML first.', 'What does "no ARIA is better than bad ARIA" mean?', 'Incorrect ARIA actively misleads screen readers — worse than none. Prefer native elements (a real `button`), which come with correct semantics for free.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What does the `tabindex` attribute do?', 'Controls keyboard focus: `0` joins the natural tab order, `-1` is focusable only via JS, positive values force a specific order.', 'Why is a positive `tabindex` (like 3) an anti-pattern?', 'It overrides natural DOM order, creating a confusing, fragile focus sequence. Stick to `0` (in order) and `-1` (JS-focusable only).', 'intermediate', 'approved', 'core'),
  ('HTML', 'What is the `<label>`''s `for` attribute?', 'It links a label to a control by matching the control''s `id`, so clicking the label focuses the input and screen readers announce it.', 'Name two benefits of associating a label with an input.', 'Clicking the label focuses/activates the control (larger hit target), and screen readers announce the label when the field is focused.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What are responsive images with `srcset` / `<picture>`?', '`srcset` lets the browser pick the best image for the screen/resolution. `<picture>` with `<source>` enables art direction (different crops) or format fallbacks.', '`srcset` vs `<picture>` — when do you need `<picture>`?', 'Use `srcset` for the same image at different resolutions (browser picks). Use `<picture>` for genuinely different crops (art direction) or format fallbacks like WebP → JPEG.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Difference between `<ol>`, `<ul>`, and `<dl>`?', '- `ol`: ordered (numbered) — order matters.
- `ul`: unordered (bulleted) — order doesn''t.
- `dl`: description list of term/description pairs (`dt`/`dd`).', 'When is order meaningful enough to use `<ol>`?', 'When reordering changes meaning — steps, rankings, instructions. If items are interchangeable, use `ul`.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What are meta tags used for?', '`charset` (encoding), `viewport` (responsive scaling), `description` (SEO snippet), and Open Graph tags for social previews.', 'Which meta tag controls how a link previews on social media?', 'Open Graph tags — `og:title`, `og:description`, `og:image` (Twitter/X also reads `twitter:*`).', 'intermediate', 'approved', 'core'),
  ('HTML', 'Difference between `<link>` and `<a>`?', '`link` declares a relationship to a resource (usually a stylesheet) in the `head` and isn''t clickable; `a` is a clickable navigation hyperlink in the body.', 'Both use `href` — what''s the core difference?', '`link` is a non-clickable resource relationship in the head; `a` is a clickable link that navigates the user.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What are `<fieldset>` and `<legend>`?', '`fieldset` groups related form controls (with a border); `legend` captions that group — useful for radio groups and accessibility.', 'Why group radio buttons in a fieldset?', 'The `legend` gives the group an accessible name, so screen readers announce "Shipping method: Standard" instead of just "Standard" with no context.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Explain the CSS box model.', 'Every element is a box with four layers, inside out: **content** → **padding** → **border** → **margin**. Padding is inside the border (background shows through); margin is outside (transparent, separates elements).', 'How does margin collapsing work?', 'Adjacent vertical margins collapse to the *larger* of the two, not their sum. It happens between siblings and parent/child. Padding, borders, or a flex/grid context prevent it.', 'intermediate', 'approved', 'core'),
  ('CSS', '`box-sizing: content-box` vs `border-box`?', '- **content-box** (default): `width` is content only; padding/border are added on top.
- **border-box**: `width` includes padding and border, so the box stays the size you set.', 'Why do most projects set `box-sizing: border-box` globally?', 'So width/height include padding and border — a `200px` box stays `200px`. It makes sizing predictable, especially with % widths plus padding.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Difference between margin and padding?', 'Padding is space inside the border (shows the element''s background); margin is space outside the border (transparent, separates elements).', 'Which one shows the element''s background color?', 'Padding — it''s inside the border. Margin is always transparent.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is specificity and how is it calculated?', 'It decides which conflicting rule wins, ranked high→low: inline (1000), IDs (100), classes/attributes/pseudo-classes (10), elements/pseudo-elements (1). Higher total wins; ties go to the later rule. `!important` overrides all.', 'How do you win a specificity battle without `!important`?', 'Add a qualifying selector (e.g. another class), or reorder so the winning rule comes later. Keeping selectors flat (single classes) avoids the battle entirely.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is the cascade?', 'The algorithm resolving which styles apply when rules conflict. It considers importance (`!important`), then specificity, then source order (later wins).', 'Two rules have equal specificity — which wins?', 'The one declared later in the source order.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Explain `position`: static, relative, absolute, fixed, sticky.', '- **static**: default, ignores offsets.
- **relative**: offset from its normal spot; still occupies original space.
- **absolute**: removed from flow, positioned to nearest positioned ancestor.
- **fixed**: removed from flow, positioned to the viewport.
- **sticky**: relative until a scroll threshold, then sticks.', '`sticky` isn''t sticking — what are the usual causes?', 'A missing threshold (`top: 0`), an ancestor with `overflow: hidden/auto`, or a parent that isn''t tall enough to scroll within.', 'intermediate', 'approved', 'core'),
  ('CSS', '`display: none` vs `visibility: hidden` vs `opacity: 0`?', '- **display: none**: removed from layout, takes no space, not interactive, hidden from screen readers.
- **visibility: hidden**: invisible but still takes space, not interactive.
- **opacity: 0**: invisible, takes space, and still interactive/clickable.', 'Which of the three still responds to clicks?', '`opacity: 0` — it''s fully interactive and takes space. `visibility: hidden` takes space but isn''t clickable. `display: none` is gone entirely.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is Flexbox and what are the main/cross axes?', 'A one-dimensional layout system. `flex-direction` sets the **main axis** (default `row`); the **cross axis** is perpendicular. `justify-content` aligns along main; `align-items` along cross.', 'How do `justify-content` and `align-items` relate to the axes?', '`justify-content` aligns along the main axis; `align-items` aligns along the cross axis. Flip `flex-direction` and their effects swap.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is CSS Grid and when do you use it over Flexbox?', 'Grid is **two-dimensional** (rows and columns together). Use Grid for overall page/section layouts; use Flexbox for one-dimensional arrangement (a navbar, a row of buttons).', 'Can you use both together, and when?', 'Yes, constantly — Grid for the 2D layout, Flexbox inside a grid item for its 1D content (e.g. a card''s row of buttons).', 'intermediate', 'approved', 'core'),
  ('CSS', 'Explain px, em, rem, %, vh/vw.', '- **px**: absolute pixels.
- **em**: relative to the parent''s font-size (compounds when nested).
- **rem**: relative to the root font-size (predictable).
- **%**: relative to the parent''s corresponding dimension.
- **vw/vh**: 1% of viewport width/height.', 'Why prefer `rem` over `em` for font sizing?', '`em` is relative to the parent, so nesting compounds unpredictably. `rem` is always relative to the root, staying consistent.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Pseudo-classes vs pseudo-elements?', '- **Pseudo-class** (`:hover`, `:nth-child`): targets an element in a state or position.
- **Pseudo-element** (`::before`, `::first-line`): styles or generates a specific part of an element.', 'How many colons for each, and why?', 'Pseudo-classes use one colon (`:hover`); pseudo-elements use two (`::before`) to distinguish parts/generated content (single colon still works for legacy ones).', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is `z-index` and a stacking context?', '`z-index` controls front-to-back order of positioned elements — but only within the same **stacking context**. New contexts are created by `position`+`z-index`, `opacity < 1`, `transform`, `filter`, etc.', 'Why might `z-index: 9999` still not bring an element to the front?', 'Because z-index only competes within the same stacking context. If an ancestor sits in a lower context, its child can''t escape. Look for a parent with opacity/transform/z-index creating a context.', 'intermediate', 'approved', 'core'),
  ('CSS', 'How does inheritance work in CSS?', 'Some properties (mostly text: `color`, `font-family`, `line-height`) inherit by default; layout properties (`margin`, `border`, `width`) don''t. Force with `inherit`; reset with `unset`.', 'Name a property that inherits and one that doesn''t.', '`color` inherits; `border` (and most layout properties) doesn''t.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What are CSS combinators?', '- **Descendant** (`A B`): any B inside A.
- **Child** (`A > B`): direct children only.
- **Adjacent sibling** (`A + B`): the B right after A.
- **General sibling** (`A ~ B`): all B siblings after A.', 'Difference between `A + B` and `A ~ B`?', '`+` selects only the single sibling immediately after A; `~` selects all following siblings of A.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is a media query? Mobile-first vs desktop-first?', 'Conditional CSS based on device traits (usually width). Mobile-first uses `min-width` and enhances upward; desktop-first uses `max-width` and scales down.', 'Why is mobile-first generally preferred?', 'Base styles serve the most constrained device and you progressively enhance — which tends to produce simpler CSS and better mobile performance.', 'intermediate', 'approved', 'core'),
  ('CSS', 'How do you center a `<div>` horizontally and vertically?', 'Flexbox:
```css
.parent {
  display: flex;
  justify-content: center; /* horizontal */
  align-items: center;     /* vertical */
}
```
Or Grid: `display: grid; place-items: center;`.', 'How do you center a single `position: absolute` element?', '`top: 50%; left: 50%; transform: translate(-50%, -50%);` — the translate offsets by the element''s own size, so it''s truly centered.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What are CSS custom properties (variables)?', 'Reusable values: `:root { --primary: #3b82f6; }` then `color: var(--primary);`. Unlike Sass variables, they''re live at runtime and they cascade/inherit — perfect for theming.', 'How do CSS variables differ from Sass variables?', 'CSS custom properties are live at runtime — changeable with JS, they cascade and inherit. Sass variables are compiled away at build time and are static.', 'intermediate', 'approved', 'core'),
  ('CSS', '`transition` vs `animation`?', '- **transition**: animates between two states, triggered by a change (e.g. `:hover`).
- **animation** (with `@keyframes`): multiple steps, can loop, runs automatically without a trigger.', 'You need something to animate automatically on page load — which?', '`animation` with `@keyframes` — it runs without a trigger. `transition` needs a state change.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Does `transform` affect layout?', 'No. `transform` (translate/scale/rotate) is applied at paint/composite and doesn''t trigger reflow — it won''t push other elements around. That''s why animating `transform`/`opacity` is performant.', 'Why is animating `transform` smoother than animating `left`?', '`transform` is composited (often on the GPU) and skips layout; animating `left` triggers layout every frame, causing jank.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Reflow (layout) vs repaint?', '- **Reflow**: recalculating positions/geometry (changing size, adding elements) — expensive.
- **Repaint**: redrawing pixels without layout changes (color, background) — cheaper.', 'Give an example that triggers reflow vs one that only repaints.', 'Changing width or adding a DOM node → reflow. Changing color/background → repaint only. Reflows are more expensive.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What are the values of `overflow`?', '`visible` (spills out), `hidden` (clipped), `scroll` (always shows bars), `auto` (bars only when needed).', 'Difference between `scroll` and `auto`?', '`scroll` always shows scrollbars even when unneeded; `auto` shows them only when content overflows.', 'intermediate', 'approved', 'core'),
  ('CSS', '`:nth-child()` vs `:nth-of-type()`?', '`:nth-child(2)` matches if the element is the 2nd child of any type; `:nth-of-type(2)` matches the 2nd child of that specific type.', '`p:nth-child(2)` selects nothing — why?', 'Because the 2nd child isn''t a `p`. `nth-child` counts all children regardless of type; use `p:nth-of-type(2)` to target the 2nd paragraph.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is `float` and `clear`?', '`float` was for wrapping text around images (later abused for layout). Floated elements leave normal flow, so parents can collapse; `clear` / a clearfix fixes it. Largely replaced by Flexbox/Grid.', 'What problem does a "clearfix" solve?', 'A container with only floated children collapses to zero height. Clearfix (or `overflow:auto`, or modern flex/grid) forces it to contain its floats.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What is BEM?', '**Block Element Modifier** — a naming convention: `.block`, `.block__element`, `.block--modifier` (e.g. `.card`, `.card__title`, `.card--featured`). Reduces specificity conflicts.', 'How does BEM help with specificity?', 'Every selector is a single flat class of equal, low specificity, so overrides are predictable and you avoid deep high-specificity chains.', 'intermediate', 'approved', 'core'),
  ('CSS', 'When should you use `!important`, and why avoid it?', 'It forcibly overrides everything. Avoid it because it breaks the natural cascade, is hard to override (needs another `!important`), and complicates debugging. Legitimate uses are rare.', 'You must override a third-party inline style you can''t edit — options?', 'Inline styles beat normal rules, so you''d need `!important` (inline + `!important` still wins for inline). Better long-term: raise specificity if possible, or wrap/replace the component.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Difference between `min-width`, `max-width`, and `width`?', '`width` is the target; `min-width` is a floor (won''t shrink below); `max-width` is a ceiling (won''t grow beyond) — great for responsive containers.', 'What''s a common responsive use of `max-width`?', 'Capping a content container: `max-width: 1200px; margin: 0 auto;` — it fills small screens but stops growing on large ones.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Inline vs internal vs external CSS?', '- **Inline** (`style="..."`): highest specificity, not reusable — avoid.
- **Internal** (`<style>`): page-specific.
- **External** (`.css` via `link`): reusable, cacheable — best practice.', 'Why is external CSS best for performance?', 'It''s cacheable across pages and keeps HTML small. Inline/internal styles are re-downloaded with every page and aren''t shared.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`var` vs `let` vs `const`?', '- **var**: function-scoped, hoisted (initialized `undefined`), redeclarable — legacy.
- **let**: block-scoped, reassignable, not redeclarable in the same scope.
- **const**: block-scoped, not reassignable.', 'Does `const arr = []` mean the array can''t change?', 'No — only the *binding* is constant. You can push/mutate the array''s contents; you just can''t reassign `arr` to a new value.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is hoisting?', 'JS moves **declarations** to the top of their scope before execution. `var` is hoisted and set to `undefined`; `let`/`const` are hoisted but uninitialized (Temporal Dead Zone); function declarations are hoisted entirely.', 'What''s the Temporal Dead Zone?', 'The span between a `let`/`const` entering scope and being initialized. Accessing it there throws a ReferenceError — unlike `var`, which would be `undefined`.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`==` vs `===`?', '`===` (strict): compares value and type, no coercion. `==` (loose): coerces types first, so `0 == "0"` is `true`. Prefer `===`.', 'Is there a legitimate use for `==`?', 'Yes: `x == null` checks for both `null` and `undefined` in one comparison. Otherwise prefer `===`.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is a closure?', 'A function that remembers variables from the scope where it was created, even after that outer function returns:
```js
function counter() {
  let count = 0;
  return () => ++count;
}
const inc = counter();
inc(); // 1
inc(); // 2  — count is "closed over"
```', 'What''s a classic closure bug with loops?', 'Using `var` in a loop with async callbacks — all callbacks share one variable and see its final value. `let` (block-scoped per iteration) fixes it.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is the `this` keyword?', 'It refers to the execution context, decided by *how a function is called*: global/undefined for plain calls, the object for methods, the explicit value with call/apply/bind, the new instance with `new`, and the enclosing scope for arrow functions.', 'Why do arrow functions "fix" `this` in callbacks?', 'They don''t have their own `this`; they capture it lexically from the enclosing scope, so a method''s `this` is preserved inside the callback.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Arrow functions vs regular functions?', 'Arrows have no own `this` (lexical), no `arguments` object, can''t be constructors (`new`), and can''t be generators. They''re always expressions.', 'Can you use an arrow function as an object method that needs `this`?', 'Not reliably — an arrow method''s `this` is the surrounding scope (often the module/window), not the object. Use a regular function for methods.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is the event loop?', 'JS is single-threaded. Synchronous code runs on the call stack; async callbacks wait in queues. When the stack empties, the loop pushes queued callbacks. **Microtasks** (promises) run before **macrotasks** (setTimeout) each tick.', '`setTimeout(fn, 0)` vs `Promise.resolve().then(fn)` — which runs first?', 'The promise. Microtasks drain completely before the next macrotask, even with a 0ms timeout.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Synchronous vs asynchronous?', 'Synchronous code runs line by line, each statement blocking the next. Asynchronous operations run in the background and their callbacks fire later, so the main thread isn''t blocked.', 'Does async code run on a separate thread in JS?', 'No — JS is single-threaded. The host (browser/Node) handles the timer/network in the background, then queues the callback for the single main thread.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What are Promises and their states?', 'A promise represents a future value. Three states: **pending**, **fulfilled** (resolved with a value), **rejected** (failed). Once settled it can''t change; promises are chainable and solve callback hell.', 'Once a promise is rejected, can it become fulfilled?', 'No — a promise settles exactly once and its state is then immutable.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is `async`/`await`?', 'Syntactic sugar over promises so async code reads synchronously. An `async` function returns a promise; `await` pauses until the awaited promise settles; errors use `try/catch`:
```js
async function getUser() {
  try {
    const res = await fetch(''/api/user'');
    return await res.json();
  } catch (e) { console.error(e); }
}
```', 'How do you run two awaits in parallel instead of sequentially?', 'Start both first, then await together: `const [a, b] = await Promise.all([f1(), f2()])`. Awaiting one and then the other runs them serially.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`null` vs `undefined`?', '`undefined` = declared but unassigned, or a missing value (JS''s default). `null` = an intentional "no value" set by the developer.', 'What does `typeof null` return, and is it a bug?', '`"object"` — yes, a long-standing bug kept for backward compatibility.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What are truthy and falsy values?', 'Falsy: `false`, `0`, `-0`, `0n`, `""`, `null`, `undefined`, `NaN`. Everything else is truthy — including `"0"`, `[]`, and `{}`.', 'Is an empty array `[]` truthy or falsy?', 'Truthy — objects and arrays are always truthy, even when empty. Only the ~7 falsy values are false.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`map` vs `filter` vs `reduce` vs `forEach`?', '- **map**: new array by transforming each element.
- **filter**: new array of elements that pass a test.
- **reduce**: reduces to a single value.
- **forEach**: iterates for side effects, returns `undefined`.', 'Why can''t you chain after `forEach`?', '`forEach` returns `undefined` (it''s for side effects). `map`/`filter` return new arrays, so they chain.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Spread vs rest operator?', 'Same `...` syntax, opposite jobs: **spread** expands an iterable (`[...arr]`, `{...obj}`); **rest** collects items into one array (`function sum(...nums)`).', 'Does spreading an object deep-clone it?', 'No — `{...obj}` is a shallow copy; nested objects/arrays are still shared by reference.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is destructuring?', 'Unpacking values into variables: `const [a, b] = [1, 2]`, `const { name, age } = user`, with defaults `const { city = ''NYC'' } = user`.', 'How do you rename a variable while destructuring?', '`const { name: userName } = user;` — the colon renames the extracted property.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`call` vs `apply` vs `bind`?', 'All set `this` explicitly. `call(thisArg, a, b)` invokes now with listed args; `apply(thisArg, [args])` invokes now with an array; `bind(thisArg)` returns a new bound function.', '`call` vs `apply` — the only difference?', 'How arguments are passed: `call` takes a list, `apply` takes a single array. `bind` returns a new function instead of calling.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is prototypal inheritance?', 'Objects inherit via the **prototype chain**: property lookup walks from the object up its prototypes until found or `null`. It''s how methods like `.map()` are shared without copying onto every instance.', 'Where does `arr.map` actually live?', 'On `Array.prototype`. Each array delegates up the chain to find it rather than owning a copy.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Event bubbling, capturing, and delegation?', '**Bubbling**: an event propagates up from the target (default). **Capturing**: down from the root (opt-in). **Delegation**: one listener on a parent handles many children via `event.target`.', 'Why is event delegation useful for a dynamic list?', 'One listener on the parent handles current *and* future children via `event.target` — no need to (re)bind a listener to each item.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Function declaration vs function expression?', 'Declaration `function foo(){}` is fully hoisted (callable before its line). Expression `const foo = function(){}` isn''t — only the variable is hoisted, not the assignment.', 'Can you call a function expression before its line?', 'No — only the variable is hoisted (as `undefined`), not the function. Declarations are fully hoisted and callable earlier.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is a callback?', 'A function passed as an argument to be called later — e.g. `arr.forEach(cb)` or an event handler. The basis of async programming before promises.', 'What is "callback hell"?', 'Deeply nested callbacks for sequential async steps, making code hard to read and error-handle. Promises/async-await flatten it.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Shallow copy vs deep copy?', 'Shallow copies top-level properties but shares nested references (`{...obj}`, `Object.assign`). Deep fully clones every level with no shared references.', 'What''s a modern built-in for deep cloning?', '`structuredClone(obj)` — handles nested data, Dates, Maps, etc. (`JSON.parse(JSON.stringify())` loses functions, turns Dates into strings, and breaks on cycles.)', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What are template literals?', 'Backtick strings with interpolation and multi-line support: `` `Hello ${name}, ${count} messages` ``.', 'What''s a tagged template literal?', 'A function placed before the backticks that receives the string parts and interpolated values, letting you process them (used by libraries like styled-components).', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`slice` vs `splice`?', '`slice(start, end)` returns a copy of a portion — non-mutating. `splice(start, deleteCount, ...items)` mutates the array (removes/inserts) and returns removed items.', 'Which one mutates the original array?', '`splice` mutates in place; `slice` returns a copy and leaves the original untouched.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Primitive vs reference types?', 'Primitives (string, number, boolean, null, undefined, symbol, bigint) are stored by value. Reference types (objects, arrays, functions) are stored by reference — copying copies the pointer.', 'Why does assigning then mutating one object sometimes change another?', 'For objects/arrays both variables hold the same reference. Primitives are copied by value, so this doesn''t happen with them.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`JSON.parse` and `JSON.stringify`?', '`stringify` converts a JS value to a JSON string (for storage/transport); `parse` converts a JSON string back to a JS value.', 'What data is lost when you `JSON.stringify` an object?', 'Functions, `undefined` values, and symbols are dropped; Dates become strings; `NaN`/`Infinity` become `null`.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Debouncing vs throttling?', 'Both limit how often a function runs. **Debounce**: wait until triggering stops for X ms, then run once. **Throttle**: run at most once every X ms while triggering continues.', 'Search-as-you-type vs a scroll handler — which technique for each?', 'Debounce for search (act after typing stops); throttle for scroll (act at a steady max rate while scrolling).', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`setTimeout` vs `setInterval`?', '`setTimeout(fn, ms)` runs once after the delay; `setInterval(fn, ms)` runs repeatedly until `clearInterval`.', 'Why can `setInterval` callbacks "pile up"?', 'If a callback takes longer than the interval (heavy work or a busy thread), executions queue up. A recursive `setTimeout` avoids this by scheduling the next only after the current finishes.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What are higher-order functions?', 'Functions that take a function as an argument and/or return a function — e.g. `map`, `filter`, `setTimeout`. They enable composition and abstraction.', 'Is `map` a higher-order function? Why?', 'Yes — it takes a function as an argument. HOFs take and/or return functions.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`innerHTML` vs `textContent` vs `innerText`?', '`innerHTML` gets/sets HTML (parses tags — XSS risk). `textContent` gets/sets raw text (fast, safe). `innerText` is layout-aware (respects `display:none`, triggers reflow — slower).', 'Why avoid `innerHTML` with user input?', 'It parses the string as HTML, so untrusted input can inject scripts (XSS). Use `textContent`, or sanitize the input.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is short-circuit evaluation?', 'Logical operators stop once the result is known: `a && b` returns `a` if falsy else `b`; `a || b` returns `a` if truthy else `b` (common for defaults).', 'What does `a || b` return exactly?', '`a` if it''s truthy, otherwise `b` — it returns the operand itself, not a boolean.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Nullish coalescing (`??`) and optional chaining (`?.`)?', '`??` returns the right side only if the left is `null`/`undefined`. `?.` safely accesses nested properties, returning `undefined` instead of throwing: `user?.address?.city`.', 'How does `??` differ from `||` for defaults?', '`??` only falls back on `null`/`undefined`, so `0 ?? 5` is `0`. `||` falls back on any falsy value, so `0 || 5` is `5`.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is `NaN` and how do you check for it?', '"Not a Number" — the result of invalid math. It''s the only value not equal to itself, so `NaN === NaN` is `false`.', 'How do you reliably test if a value is `NaN`?', '`Number.isNaN(x)`. You can''t use `x === NaN`. (Global `isNaN` coerces its argument and is unreliable.)', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`addEventListener` vs `onclick`?', '`onclick` allows only one handler (a new one overwrites). `addEventListener` allows multiple handlers, capture/bubble choice, and individual removal.', 'Give one capability `addEventListener` has that `onclick` lacks.', 'Multiple handlers on the same event, plus choosing the capture phase and using options like `once`/`passive`.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is `"use strict"`?', 'Opts into strict mode: disallows undeclared globals, throws on silent errors, and makes `this` `undefined` in plain calls. ES modules and classes are strict by default.', 'Name one thing strict mode prevents.', 'Accidentally creating a global by assigning to an undeclared variable — it throws instead.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is a pure function?', 'One that always returns the same output for the same input and has no side effects (no mutation, no I/O). Predictable and easy to test.', 'Is a function that uses `Math.random()` pure?', 'No — the same input can give different output, and it depends on external state. Pure functions are deterministic with no side effects.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`find` vs `filter`?', '`find` returns the first matching element (or `undefined`); `filter` returns an array of all matches (or empty).', 'Which returns `undefined` when nothing matches?', '`find`. `filter` returns an empty array.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What does `typeof` return?', 'A type string: `"string"`, `"number"`, `"boolean"`, `"undefined"`, `"function"`, `"object"`, `"symbol"`, `"bigint"`. Note `typeof null` is `"object"` and `typeof []` is `"object"`.', 'How do you check if something is an array?', '`Array.isArray(value)` — since `typeof []` unhelpfully returns `"object"`.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'How do you select DOM elements?', '`document.querySelector(''.x'')` (first match), `document.querySelectorAll(''.x'')` (all matches as a NodeList), plus `getElementById` and friends.', '`querySelectorAll` returns a NodeList — can you call `.map` on it?', 'Not directly — a NodeList isn''t a real array. Convert first: `[...nodeList].map(...)` or `Array.from(...)`. (You *can* `forEach` a NodeList.)', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is immutability and why does it matter?', 'Not changing data after creation — you create a modified copy (`[...arr, item]`, `{...obj, key: val}`). It prevents bugs from shared references and underpins React''s change detection.', 'How do you add an item to an array immutably in React?', '`setItems([...items, newItem])` — create a new array rather than `items.push()`, so React detects the change.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`for...of` vs `for...in`?', '`for...of` iterates over **values** of an iterable (arrays, strings, Maps). `for...in` iterates over **keys** (enumerable property names) — best for objects.', 'Which should you avoid for arrays, and why?', '`for...in` — it iterates keys as strings and can pick up inherited/extra properties. Use `for...of` for array values.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What is Tailwind CSS and what does "utility-first" mean?', 'A **utility-first** CSS framework: you compose designs from small single-purpose classes (`flex`, `pt-4`, `bg-blue-500`) directly in markup, instead of writing custom CSS or using prebuilt components.', 'How do you avoid repeating the same long class list everywhere?', 'Extract a component in your framework (React/Vue) so the utilities live in one reusable place. Use `@apply` only for small, genuinely repeated patterns.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'Pros and cons of utility-first CSS?', '**Pros**: no context-switching, no naming, no dead CSS, consistent design tokens, small bundles. **Cons**: cluttered-looking markup, a learning curve, and repetition unless you extract components.', 'What''s the most common criticism, and the counter-argument?', '"Ugly, cluttered markup." The counter: styles are co-located with structure, there''s no dead CSS or naming overhead, and components hide the verbosity.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How does Tailwind handle responsive design?', 'With **mobile-first** prefixes. Unprefixed utilities apply everywhere; prefixed ones apply from that breakpoint up: `text-sm md:text-base lg:text-lg`.', 'Does `md:flex` apply only at the md breakpoint or md and up?', 'md and up — Tailwind is mobile-first, so prefixes are `min-width` and cascade upward.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What are the default breakpoints?', '`sm` 640px, `md` 768px, `lg` 1024px, `xl` 1280px, `2xl` 1536px — each a `min-width` (mobile-first).', 'What''s the default `md` breakpoint value?', '768px.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How do you apply hover, focus, and other states?', 'State variants prefix the utility: `hover:bg-blue-700 focus:ring-2 active:scale-95 disabled:opacity-50`.', 'How would you style an element only when a parent is hovered?', 'Mark the parent `group`, then use `group-hover:` on the child.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'Tailwind vs Bootstrap — the core difference?', 'Bootstrap is **component-first** (ready-made styled components, opinionated look). Tailwind is **utility-first** (unstyled primitives you compose into any design).', 'Why do Bootstrap sites often "look the same"?', 'Bootstrap ships styled components with a default look; Tailwind gives unstyled primitives, so the design is entirely yours.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How do you customize Tailwind''s theme?', '**v3**: edit `tailwind.config.js` — `theme.extend` to add, or `theme` to override. **v4**: configure in CSS with the `@theme` directive using CSS variables (`--color-brand: #ff5722;`).', 'In v4, where do you define custom theme tokens?', 'In CSS via the `@theme` directive using CSS variables, rather than the JS `tailwind.config.js` used in v3 (still supported via `@config`).', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What is `@apply` and when should you use it?', 'It pulls utility classes into a custom CSS rule: `.btn { @apply px-4 py-2 rounded bg-blue-500; }`. Use it sparingly — for small, repeated patterns.', 'Why is overusing `@apply` discouraged?', 'It recreates the big, hard-to-maintain CSS file Tailwind aims to avoid and loses co-location. Prefer component abstractions for reuse.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How does Tailwind keep the production file small?', 'It scans your source for class names and generates only those (JIT). In v3 you configure `content` paths; in v4 content detection is largely automatic. Unused utilities never ship.', 'How does Tailwind decide which classes to include?', 'It scans your source files for class names and generates only the ones you actually use.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How do you implement dark mode?', 'Use the `dark:` variant: `bg-white dark:bg-gray-900`. Configure the strategy: `media` (follows the OS) or `class` (toggle a `dark` class on `<html>` for a manual switch).', '`media` strategy vs `class` strategy — when to use `class`?', 'Use `class` when you want a manual toggle (user switches themes); `media` just follows the OS setting with no toggle.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What are arbitrary values?', 'Square-bracket syntax for one-off values not in your scale: `top-[117px]`, `bg-[#1da1f2]`, `w-[32rem]`, `grid-cols-[1fr_2fr]`.', 'How do you set an exact one-off value like `top: 117px`?', 'Square-bracket syntax: `top-[117px]`.', 'intermediate', 'approved', 'core'),
  ('Tailwind', '`theme.extend` vs overriding `theme` directly (v3)?', '`extend` **adds** to the defaults (keeps built-ins). Overriding `theme` directly **replaces** that section — e.g. defining `theme.colors` wipes the default palette.', 'What happens if you set `theme.colors` directly (not extend)?', 'You replace Tailwind''s entire default palette — all built-in colors disappear. Use `extend` to add while keeping defaults.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What is the spacing scale?', 'A consistent numeric scale for `p-`, `m-`, `w-`, `gap-`, etc. Each unit is `0.25rem` (4px), so `p-4` is `1rem` (16px).', 'How many pixels is `p-4`?', '16px — the scale is 0.25rem per unit, so 4 × 4px = 16px.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How do you handle conditional classes in React?', 'Use a helper since classes are strings: `clsx(''px-4 py-2'', isActive && ''bg-blue-500'')`. Libraries like `clsx`/`classnames` (plus `tailwind-merge`) keep it clean.', 'How do you resolve conflicting classes like `p-2` and `p-4` conditionally?', 'Use `tailwind-merge` (often with `clsx`) — it keeps the last conflicting utility so the intended one wins.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'Difference between `p-4`, `px-4`, and `py-4`?', '`p-4` pads all sides; `px-4` pads left+right (x-axis); `py-4` pads top+bottom (y-axis). Same pattern for margins and single sides (`pt`, `pr`, `pb`, `pl`).', 'What does `px-` affect?', 'Horizontal padding — left and right (x-axis). `py-` is vertical.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What are `group` and `peer` modifiers?', 'They let an element style itself based on another element''s state. `group` + `group-hover:` styles children from a parent''s state; `peer` + `peer-checked:` styles a following sibling.', '`peer` vs `group` — what''s the structural difference?', '`group` styles descendants based on an ancestor''s state; `peer` styles a *following sibling* based on a preceding sibling''s state (great for input→label).', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What does `@layer` do?', 'It organizes custom CSS into Tailwind''s layers (`base`, `components`, `utilities`) so styles sort correctly and are purged properly: `@layer components { .btn { @apply px-4 py-2; } }`.', 'Why put custom classes inside `@layer components`?', 'So they sort into Tailwind''s layer order (correct precedence) and are included/purged like built-in utilities.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'Utility classes vs hand-written CSS — the trade-off?', 'Utilities give speed, consistency, and no dead CSS with co-located styling. Hand-written CSS gives cleaner markup. Many teams use Tailwind for the bulk and drop to CSS for complex cases.', 'When would you still drop to hand-written CSS?', 'Complex keyframe animations, intricate pseudo-element art, or highly dynamic values utilities handle awkwardly — usually via `@layer`/`@apply` or a small CSS file.', 'intermediate', 'approved', 'core'),
  ('React', 'What is React?', 'A JavaScript library for building UIs from reusable, composable **components**. It''s declarative (you describe UI for a given state) and uses a virtual DOM to update efficiently.', 'Is React a framework?', 'Technically a *library* focused on the view layer — routing and data fetching come from other libraries or meta-frameworks like Next.js. People often call it a framework loosely.', 'intermediate', 'approved', 'core'),
  ('React', 'What is the virtual DOM?', 'An in-memory representation of the UI. On a state change, React builds a new tree, diffs it against the old one (reconciliation), and applies the minimal real-DOM updates.', 'Does the virtual DOM make React faster than vanilla DOM manipulation?', 'Not inherently — hand-tuned direct edits can be faster. Its value is a simpler declarative model with good-enough batched updates, not raw speed.', 'intermediate', 'approved', 'core'),
  ('React', 'What is JSX?', 'A syntax extension for writing HTML-like markup in JS; it compiles to `React.createElement` calls. `className` replaces `class`, attributes are camelCase, and `{}` embeds JS expressions.', 'Why must JSX have a single root element (or Fragment)?', 'It compiles to a single function return / createElement call — you can''t return two siblings. A Fragment (`<>...</>`) groups them without adding a DOM node.', 'intermediate', 'approved', 'core'),
  ('React', 'Function components vs class components?', 'Both produce UI. Function components are plain functions using **Hooks** for state/lifecycle; class components use `this.state` and lifecycle methods. Function components + Hooks are the modern standard.', 'Why did the ecosystem move from class to function components?', 'Hooks let you reuse stateful logic without wrapper hell (HOCs/render props), with less boilerplate and no confusing `this` binding.', 'intermediate', 'approved', 'core'),
  ('React', 'Props vs state?', '**Props** are passed into a component from its parent and are read-only. **State** is data a component owns internally and can change over time, triggering a re-render.', 'Can a component change its own props?', 'No — props are immutable from the child''s view. To "change" them, the parent updates the state it passes down, or the child calls a callback prop.', 'intermediate', 'approved', 'core'),
  ('React', 'What does `useState` do?', 'Adds state to a function component: `const [count, setCount] = useState(0)`. Calling the setter schedules a re-render with the new value.', 'Why might two rapid `setCount(count + 1)` calls only increment once?', 'Both read the same stale `count` from that render. Use the updater form `setCount(c => c + 1)` to base it on the latest value.', 'intermediate', 'approved', 'core'),
  ('React', 'What does `useEffect` do?', 'Runs side effects (data fetching, subscriptions, manual DOM work) after render. The dependency array controls when it re-runs; a returned function is cleanup.', 'What''s the difference between `[]`, `[dep]`, and no dependency array?', '`[]` runs once on mount. `[dep]` runs on mount and whenever `dep` changes. No array runs after *every* render — usually a bug.', 'intermediate', 'approved', 'core'),
  ('React', 'Why do lists need a `key` prop?', 'A stable `key` gives each item an identity so React can match elements across renders and update efficiently instead of re-creating them.', 'Why is using the array index as a key risky?', 'If the list reorders, inserts, or deletes, indices shift and React mis-matches items — causing wrong state/DOM (e.g. input values attaching to the wrong row). Use a stable unique id.', 'intermediate', 'approved', 'core'),
  ('React', 'Controlled vs uncontrolled components?', 'A **controlled** input''s value is driven by React state (`value` + `onChange`). An **uncontrolled** input keeps its value in the DOM, read via a ref when needed.', 'When would you choose uncontrolled?', 'For simple forms, file inputs, or integrating non-React code — less re-rendering. Controlled is preferred when you need live validation or derived UI.', 'intermediate', 'approved', 'core'),
  ('React', 'What is "lifting state up"?', 'Moving shared state to the closest common ancestor of the components that need it, then passing it down via props — keeping them in sync.', 'What problem does lifting state up too far cause?', 'Prop drilling — passing props through many intermediate components that don''t use them. Context or a state library solves that.', 'intermediate', 'approved', 'core'),
  ('React', 'Prop drilling and the Context API?', 'Prop drilling is threading props through many layers. **Context** provides a value to a subtree without manual passing: `createContext`, a `Provider`, and `useContext`.', 'Does Context replace state-management libraries like Redux?', 'For low-frequency global values (theme, auth), yes. For large, frequently-updating state it can cause broad re-renders — where Redux/Zustand and selectors help.', 'intermediate', 'approved', 'core'),
  ('React', 'What does `useRef` do?', 'Returns a mutable `.current` container that persists across renders **without** triggering re-renders. Used to reference DOM nodes or store mutable values (timers, previous values).', 'Why not just use a normal variable instead of `useRef`?', 'A normal variable is re-created every render and doesn''t persist. A ref keeps the same object across renders, so its value survives.', 'intermediate', 'approved', 'core'),
  ('React', '`useMemo` vs `useCallback`?', '`useMemo` memoizes a computed **value**; `useCallback` memoizes a **function identity**. Both skip recomputation unless dependencies change.', 'When does memoization actually hurt?', 'For cheap computations, the caching + dependency-comparison overhead can exceed the savings and adds complexity. Only memoize expensive work or references passed to memoized children.', 'intermediate', 'approved', 'core'),
  ('React', 'What is `React.memo`?', 'A higher-order component that skips re-rendering when props are unchanged (shallow compare). Useful for expensive pure components.', 'Why might `React.memo` not prevent a re-render even with "same" props?', 'If a prop is a new object/array/function created inline each render, the shallow compare sees a different reference. Stabilize it with `useMemo`/`useCallback`.', 'intermediate', 'approved', 'core'),
  ('React', 'What are custom hooks?', 'Reusable functions starting with `use` that compose built-in hooks to share stateful logic (e.g. `useFetch`, `useLocalStorage`) between components.', 'Do two components using the same custom hook share state?', 'No — each call gets its own independent state. Hooks share *logic*, not state instances.', 'intermediate', 'approved', 'core'),
  ('React', 'What are the Rules of Hooks?', 'Call hooks only at the top level (never in loops/conditions/nested functions) and only from React functions. This keeps their call order stable across renders.', 'Why does calling a hook conditionally break React?', 'React tracks hook state by call order. A conditional call changes that order between renders, so state gets mismatched to the wrong hook.', 'intermediate', 'approved', 'core'),
  ('React', 'What is a Fragment?', 'Lets you return multiple elements without an extra wrapper DOM node: `<>...</>` or `<React.Fragment>` (use the long form when you need a `key`).', 'Why not just wrap everything in a `<div>`?', 'Extra wrapper divs can break CSS layouts (flex/grid) and bloat the DOM. Fragments group without adding a node.', 'intermediate', 'approved', 'core'),
  ('React', 'How do you do conditional rendering?', 'With ternaries, `&&`, or early returns: `{isLoading ? <Spinner/> : <List/>}`.', 'What''s the bug with `{count && <List/>}` when count is 0?', 'It renders `0` on screen (0 is falsy but a valid React child). Use `count > 0 && ...` or a ternary.', 'intermediate', 'approved', 'core'),
  ('React', 'What are synthetic events?', 'React wraps native events in a cross-browser `SyntheticEvent` with a consistent API, handled via delegation at the root. Handlers use camelCase (`onClick`).', 'How do you stop a click from bubbling in React?', '`e.stopPropagation()` in the handler — the SyntheticEvent exposes the familiar `preventDefault`/`stopPropagation` methods.', 'intermediate', 'approved', 'core'),
  ('React', 'What are lazy loading and Suspense?', '`React.lazy(() => import(''./X''))` code-splits a component so it loads on demand; wrap it in `<Suspense fallback={...}>` to show a placeholder while it loads.', 'What''s the main benefit of code-splitting with `lazy`?', 'A smaller initial bundle — users download route/feature code only when needed, improving first load.', 'intermediate', 'approved', 'core'),
  ('React', 'What does `useReducer` do?', 'An alternative to `useState` for complex/related state: `const [state, dispatch] = useReducer(reducer, initial)`. You dispatch actions and a reducer returns the next state.', 'When is `useReducer` preferable to `useState`?', 'When state has multiple sub-values that change together, the next state depends on the previous, or update logic is complex — a reducer centralizes it and is easy to test.', 'intermediate', 'approved', 'core'),
  ('React', 'Why shouldn''t you mutate state directly?', 'React compares references to decide whether to re-render. Mutating in place (`state.push()`) keeps the same reference, so React may skip the update. Always create new objects/arrays.', 'What''s the practical symptom of mutating state?', 'The UI doesn''t update even though the data "changed" — a very common beginner bug.', 'intermediate', 'approved', 'core'),
  ('React', 'What is `useEffect` cleanup?', 'The function returned from `useEffect` runs before the effect re-runs and on unmount — used to remove listeners, cancel timers, or abort requests.', 'What bug happens if you forget cleanup on a subscription?', 'Memory leaks and duplicate subscriptions/handlers stacking up on every re-run — plus warnings about updating state on an unmounted component.', 'intermediate', 'approved', 'core'),
  ('React', '`useLayoutEffect` vs `useEffect`?', 'Both run after render, but `useLayoutEffect` fires synchronously **before the browser paints**, while `useEffect` fires after paint. Use layout effect only to measure/mutate the DOM before it''s visible.', 'Why prefer `useEffect` by default?', '`useLayoutEffect` blocks painting, which can cause jank. Reach for it only to avoid a visible flicker (e.g. measuring layout then adjusting).', 'intermediate', 'approved', 'core'),
  ('React', 'What are error boundaries?', 'Components that catch JS errors in their child tree and render a fallback instead of crashing the app. Implemented with class components (`getDerivedStateFromError`/`componentDidCatch`).', 'What errors do error boundaries NOT catch?', 'Errors in event handlers, async code, SSR, and errors thrown in the boundary itself. Handle those with `try/catch`.', 'intermediate', 'approved', 'core'),
  ('React', 'What is reconciliation?', 'React''s diffing process: it compares the new element tree with the old one and updates only what changed, assuming different element types produce different trees and using keys to match list children.', 'What happens if a component''s type changes between renders (e.g. `<div>` → `<span>`)?', 'React tears down the old subtree and its state and builds a fresh one — state is lost. The same type reuses the instance and just updates props.', 'intermediate', 'approved', 'core'),
  ('React', 'What is StrictMode?', 'A dev-only wrapper that surfaces problems by double-invoking certain functions (render, effects) to expose impure logic and missing cleanups. It has no effect in production.', 'Why does my effect run twice in development?', 'StrictMode intentionally mounts, unmounts, and remounts once in dev to catch missing cleanup. It won''t double-run in production.', 'intermediate', 'approved', 'core'),
  ('React', 'What''s new in React 19?', '**Actions** with `useActionState`/`useFormStatus` for form/async handling, the `use()` hook to read promises/context, `useOptimistic` for optimistic UI, and passing `ref` as a regular prop (no more `forwardRef` in many cases).', 'What does the `use()` hook let you do that hooks couldn''t before?', 'It can read a promise or context and can be called *conditionally* (unlike other hooks), enabling cleaner data reads and Suspense integration.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What is TypeScript and why use it?', 'A typed **superset of JavaScript** that compiles to plain JS. It adds static types checked at build time — catching errors before runtime and improving tooling (autocomplete, refactoring, self-documentation).', 'Does TypeScript add any runtime type checking?', 'No — types are erased at compile time. For runtime validation (e.g. API responses) use a library like Zod.', 'intermediate', 'approved', 'core'),
  ('TypeScript', '`type` vs `interface`?', 'Both describe object shapes. `interface` is extendable and supports declaration merging — ideal for objects/classes. `type` is more flexible: it can alias unions, primitives, tuples, and mapped types.', 'When must you use `type` over `interface`?', 'For unions, tuples, primitives, or complex mapped/conditional types — interfaces can''t express those. For plain object shapes, either works.', 'intermediate', 'approved', 'core'),
  ('TypeScript', '`any` vs `unknown` vs `never`?', '`any` opts out of type checking (dangerous). `unknown` is a safe top type — you must narrow it before use. `never` represents values that never occur (a function that always throws, an impossible branch).', 'Why prefer `unknown` over `any` for an API response?', '`unknown` forces you to check/narrow before using the value, preserving safety. `any` silently disables all checks and lets bugs through.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'Union vs intersection types?', 'Union `A | B` = a value is *one of* several types. Intersection `A & B` = it has *all* members of several types combined.', 'What does `string & number` resolve to?', '`never` — no value can be both a string and a number at once, so the intersection is empty.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are generics?', 'Type parameters that keep code reusable while preserving type info: `function identity<T>(x: T): T`. The caller''s type flows through instead of widening to `any`.', 'How do you constrain a generic to objects with an `id`?', '`<T extends { id: number }>` — the `extends` clause restricts what `T` can be.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are enums?', 'A named set of constants: `enum Role { Admin, User }`. Numeric enums auto-increment; string enums assign explicit strings. They exist at runtime (unlike types).', 'Why do some teams prefer union literal types over enums?', '`type Role = ''admin'' | ''user''` is simpler, tree-shakeable, and emits no runtime code, while giving the same type safety.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'How do optional properties work?', 'Mark them with `?`: `interface User { name: string; age?: number }`. Optional props may be `undefined` and can be omitted entirely.', 'What''s the difference between `age?: number` and `age: number | undefined`?', 'With `?` you can omit the property. With `| undefined` (no `?`) the property must be present but may be set to `undefined`.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What is type inference?', 'TS deduces types when you don''t annotate: `let x = 5` is inferred as `number`. It cuts boilerplate while keeping safety.', 'Should you annotate everything explicitly?', 'No — lean on inference for locals and return values; annotate parameters, public APIs, and anywhere inference is wrong or unclear.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What is a type assertion (`as`)?', 'It tells the compiler to treat a value as a specific type: `const el = document.getElementById(''x'') as HTMLInputElement`. A compile-time override, not a runtime cast.', 'What''s the danger of `as`?', 'You override the compiler — if you assert wrongly, TS won''t catch the resulting runtime error. Prefer narrowing/guards when possible.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are literal types?', 'Types that are an exact value, not just the primitive: `let dir: ''left'' | ''right''`. Great for restricting to a fixed set of allowed values.', 'How do you make an object''s properties literal types automatically?', '`as const` — it narrows all values to their literals and makes them readonly.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are tuples?', 'Fixed-length arrays with a known type per position: `let pair: [string, number]`.', 'How does React''s `useState` use tuples?', 'It returns `[value, setter]` as a tuple, so destructuring gives a correctly-typed value and setter by position.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What does `readonly` do?', 'Prevents reassigning a property after creation: `readonly id: number`, or `readonly T[]` / `ReadonlyArray<T>` for arrays.', 'Is `readonly` enforced at runtime?', 'No — it''s compile-time only. At runtime the value can still be mutated by untyped code.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are utility types?', 'Built-in type transformers: `Partial<T>` (all optional), `Required<T>`, `Readonly<T>`, `Pick<T,K>`, `Omit<T,K>`, `Record<K,V>`, `Exclude`, `Extract`, `ReturnType<T>`.', 'How would you type an update function that takes some fields of `User`?', '`Partial<User>` — makes every property optional so callers pass only what changes.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What do `keyof` and `typeof` do?', '`keyof T` gives a union of a type''s keys. `typeof value` gives the type of a runtime value. Combine them: `keyof typeof obj` derives key types from an object.', 'How do you type a function that accepts only valid keys of an object?', '`function get<T, K extends keyof T>(obj: T, key: K): T[K]` — `K` is constrained to real keys and the return is the indexed value type.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are type guards / narrowing?', 'Runtime checks that let TS narrow a type within a branch: `typeof x === ''string''`, `Array.isArray(x)`, `''prop'' in obj`, or a custom `x is Type` predicate.', 'What''s a user-defined type guard?', 'A function returning `param is SomeType` (e.g. `function isCat(a: Animal): a is Cat`). Inside a passing branch, TS narrows to that type.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are discriminated unions?', 'A union of object types sharing a common literal "tag" field, so TS narrows by checking the tag: `{kind:''circle'', r} | {kind:''square'', s}` switched on `kind`.', 'Why are discriminated unions great with `switch` statements?', 'TS narrows the type in each case automatically, and a `never` default can enforce that you''ve handled every variant (exhaustiveness).', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'How do function types work?', 'You can type parameters and return values: `(x: number) => string`, and type variables holding functions. Optional, default, and rest params are supported.', 'What does a return type of `void` allow that `undefined` doesn''t?', '`void` means the return is ignored — a `() => void` function may actually return anything, and callers won''t use it. `undefined` requires returning `undefined` specifically.', 'intermediate', 'approved', 'core'),
  ('TypeScript', '`void` vs `never`?', '`void` = returns nothing meaningful (but completes). `never` = never returns normally (always throws or loops forever).', 'What''s a real use of the `never` type?', 'Exhaustiveness checks — assigning the "impossible" default case to a `never` variable makes TS error if you add an unhandled union member.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What is structural typing?', 'TS type compatibility is based on **shape**, not name (duck typing). If an object has the required members, it''s assignable — regardless of declared type.', 'How does structural typing differ from Java/C# nominal typing?', 'Nominal systems require the declared type/name to match. TS only cares that the structure matches, so two unrelated types with the same shape are interchangeable.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What is the non-null assertion (`!`)?', '`value!` tells the compiler a value isn''t null/undefined here: `input!.focus()`. It removes null from the type without a runtime check.', 'What''s the risk of `!`?', 'If you''re wrong and it IS null, you get a runtime error TS could have caught. Prefer a real null check or optional chaining when unsure.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are mapped types?', 'Types that transform each property of another type: `{ [K in keyof T]: ... }`. Utility types like `Partial`/`Readonly` are built with them.', 'Write a mapped type that makes all properties optional.', '`type MyPartial<T> = { [K in keyof T]?: T[K] }` — the `?` modifier applied over each key.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What does `as const` do?', 'Freezes a value to its most specific (literal, readonly) type: `const cfg = { mode: ''dark'' } as const` makes `mode` the literal `''dark''`, not `string`, and everything readonly.', 'How is `as const` useful for a list of allowed values?', '`const roles = [''admin'', ''user''] as const` lets you derive `type Role = typeof roles[number]` = `''admin'' | ''user''` from the runtime array.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are declaration files (`.d.ts`)?', 'Files with only type declarations (no implementation) describing the shape of JS code/libraries to TypeScript. Libraries ship them or you install `@types/x`.', 'What is DefinitelyTyped / `@types`?', 'A community repo of type definitions for JS libraries that don''t ship their own. Install them, e.g. `npm i -D @types/lodash`.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What does `strict` in tsconfig do?', '`"strict": true` enables a bundle of strict checks (`strictNullChecks`, `noImplicitAny`, and more) for maximum type safety. Recommended for new projects.', 'What does `strictNullChecks` change?', '`null` and `undefined` stop being assignable to every type — you must handle them explicitly, catching a huge class of "cannot read property of undefined" bugs.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What are the Core Web Vitals?', 'Google''s key UX metrics: **LCP** (Largest Contentful Paint — loading), **INP** (Interaction to Next Paint — responsiveness), and **CLS** (Cumulative Layout Shift — visual stability). They influence search ranking.', 'Which metric recently replaced FID, and why?', 'INP replaced First Input Delay in 2024. FID only measured the *first* interaction''s delay; INP captures overall responsiveness across *all* interactions.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is LCP and how do you improve it?', 'Largest Contentful Paint — time until the largest visible element (often a hero image or heading) renders. Good ≤ 2.5s.', 'What''s usually the #1 fix for a slow LCP?', 'Optimize the LCP resource — compress/resize the hero image, serve modern formats, preload it, and remove render-blocking CSS/JS. Improving server response (TTFB) helps too.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is INP?', 'Interaction to Next Paint — how quickly the page visually responds to interactions (clicks, taps, keys). Good ≤ 200ms.', 'What commonly causes poor INP?', 'Long JavaScript tasks blocking the main thread. Break up long tasks, defer non-critical work, and avoid heavy synchronous handlers.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is CLS and how do you avoid it?', 'Cumulative Layout Shift — how much visible content unexpectedly moves during load. Good ≤ 0.1.', 'What are the top causes of layout shift and how do you prevent them?', 'Images/ads/iframes without dimensions, and swapping web fonts. Fix by setting `width`/`height` (or `aspect-ratio`), reserving space for dynamic content, and handling `font-display` carefully.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is the critical rendering path?', 'The steps the browser takes to turn HTML/CSS/JS into pixels: parse HTML → DOM, parse CSS → CSSOM, combine into the render tree, layout, paint. Optimizing it speeds first render.', 'Why is CSS considered render-blocking?', 'The browser won''t paint until it has the CSSOM (to avoid a flash of unstyled content). So large/slow CSS delays first paint — inline critical CSS and defer the rest.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is lazy loading?', 'Deferring the load of offscreen/non-critical resources until needed. Images: `loading="lazy"`. Components: dynamic `import()` / `React.lazy`.', 'Which images should NOT be lazy-loaded?', 'Above-the-fold ones, especially the LCP image — lazy-loading them delays the largest paint. Only lazy-load offscreen content.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is code splitting?', 'Breaking the bundle into smaller chunks loaded on demand (per route/feature) rather than one giant file, so the initial download is smaller.', 'How does code splitting relate to LCP/INP?', 'Less initial JS means faster parse/execute — a quicker first render (LCP) and a less-blocked main thread (INP).', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is tree shaking?', 'Dead-code elimination at build time — bundlers drop exports you never import, shrinking the bundle. It relies on ES modules'' static structure.', 'Why can `import _ from ''lodash''` hurt tree shaking?', 'It pulls the whole library and the bundler can''t easily drop unused parts. Import specific functions (`lodash-es` or `lodash/get`) so only what you use ships.', 'intermediate', 'approved', 'core'),
  ('Performance', 'Minification vs compression?', '**Minification** strips whitespace/comments and shortens names in the code. **Compression** (gzip/Brotli) shrinks files over the wire. Both reduce bytes downloaded and they stack.', 'Minification vs compression — are they the same?', 'No. Minification rewrites the source to be smaller; compression encodes bytes for transfer and is decompressed by the browser.', 'intermediate', 'approved', 'core'),
  ('Performance', 'How do you optimize images?', 'Serve appropriately sized images, use modern formats (WebP/AVIF), set explicit dimensions, lazy-load offscreen ones, and use `srcset` for responsive resolutions.', 'How does setting width/height on an `<img>` help performance metrics?', 'It lets the browser reserve space before the image loads, preventing layout shift (better CLS).', 'intermediate', 'approved', 'core'),
  ('Performance', 'How does caching improve performance?', 'It stores responses so repeat visits skip the network: the browser HTTP cache (Cache-Control/ETag), CDNs at the edge, and Service Workers for offline/programmatic caching.', 'How do you cache assets aggressively but still ship updates?', 'Cache-bust with a content hash in the filename (e.g. `app.3f9a.js`) plus a long max-age. A change produces a new filename, so browsers fetch the new file while caching old ones.', 'intermediate', 'approved', 'core'),
  ('Performance', 'How do you reduce reflows and repaints?', 'Batch DOM reads then writes (avoid read-write-read thrashing), animate `transform`/`opacity` (compositor-only), and avoid layout-triggering changes in loops.', 'What is layout thrashing?', 'Repeatedly reading a layout property (like `offsetHeight`) then writing styles in a loop, forcing synchronous layout each time. Batch all reads before writes to avoid it.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is `requestAnimationFrame`?', 'Schedules a callback to run right before the next paint (~60fps), syncing animations to the display refresh and pausing on hidden tabs.', 'Why use rAF instead of `setInterval` for animation?', 'rAF syncs to the paint cycle (no dropped/duplicated frames), throttles when the tab is hidden, and avoids the drift/jank `setInterval` causes.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is list virtualization?', 'Rendering only the items currently visible in the viewport (plus a small buffer) instead of thousands of DOM nodes — via libraries like react-window.', 'Why does a 10,000-row list need virtualization?', 'Rendering 10k DOM nodes is slow to mount and memory-heavy, hurting responsiveness. Virtualization keeps the DOM tiny regardless of data size.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What are preload, prefetch, and preconnect?', 'Resource hints: `preload` fetches a critical resource for the current page early; `prefetch` fetches likely-next-page resources at low priority; `preconnect` warms up a connection (DNS/TLS) to another origin.', 'preload vs prefetch — what''s the difference in intent?', '`preload` = need this soon for *this* page (high priority). `prefetch` = might need this for a *future* navigation (idle, low priority).', 'intermediate', 'approved', 'core'),
  ('Performance', 'How do you reduce bundle size?', 'Ship less JS: code splitting, tree shaking, dropping heavy dependencies, dynamic imports, and analyzing with a bundle analyzer to find bloat.', 'What''s a quick way to find what''s bloating your bundle?', 'Run a bundle analyzer (webpack-bundle-analyzer / source-map-explorer) to visualize module sizes and spot large or duplicated dependencies.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What are web workers?', 'They run JavaScript on a background thread separate from the main/UI thread, communicating via messages — so heavy computation doesn''t freeze the interface.', 'What can''t a web worker do?', 'It has no direct DOM access and can''t touch `window`/`document`. It''s for CPU-bound work; results are posted back to the main thread to update the UI.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What are render-blocking resources?', 'Synchronous CSS/JS in the `<head>` that must load before the browser can render, delaying first paint. Mitigate by inlining critical CSS, deferring/asyncing JS, and lazy-loading the rest.', 'How do defer/async on scripts help here?', 'They stop scripts from blocking HTML parsing — `defer` runs after parse in order (DOM-ready), `async` runs whenever it arrives. Both unblock rendering.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What''s the difference between the App Router and the Pages Router?', '- **Pages Router** (`pages/`): file-based routes, `getStaticProps`/`getServerSideProps` for data, every route is a client/SSR React component.
- **App Router** (`app/`): built on **React Server Components**, uses nested `layout.js`/`page.js`, `async` components for data, streaming, and Server Actions.

App Router is the default for new apps since Next 13.4.', 'Can both routers coexist in one app?', 'Yes — `app/` and `pages/` can live side by side during migration. If the same path exists in both, `app/` wins. You migrate incrementally.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'In the App Router, are components server or client by default?', '**Server Components by default.** They render on the server, can be `async`, can read the filesystem/DB directly, and ship **zero JS** to the client. You opt into a Client Component with the `"use client"` directive at the top of the file.', 'What forces you to add `"use client"`?', 'Anything interactive or browser-only: hooks (`useState`/`useEffect`), event handlers (`onClick`), or Web APIs (`window`, `localStorage`). Those only work in Client Components.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What is a React Server Component (RSC)?', 'A component that runs **only on the server** and never ships its code to the browser. It can fetch data directly (`await db.query(...)`), keep secrets server-side, and shrink the client bundle. Its rendered output is serialized and streamed to the client.', 'Can a Server Component render a Client Component (and vice versa)?', 'Server can render Client, passing **serializable** props. The reverse is limited: a Client Component can''t import a Server Component, but it can receive one as `children`/props.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'How do you fetch data in an App Router Server Component?', 'Make the component `async` and `await` directly:

```jsx
export default async function Page() {
  const res = await fetch(''https://api/...'');
  const data = await res.json();
  return <List items={data} />;
}
```

No `getServerSideProps` needed.', 'Does `fetch` cache the result?', 'It depends on the version. Next 14 cached `fetch` by default (`force-cache`). **Next 15 does not cache by default** — you opt in with `cache: ''force-cache''` or `next: { revalidate }`. Always check the version.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'Explain SSR, SSG, and ISR in Next.js.', '- **SSG (static)**: HTML built at **build time**, served from CDN — fastest, for content that rarely changes.
- **SSR (server-side)**: HTML built **per request** — for personalized/always-fresh data.
- **ISR (Incremental Static Regeneration)**: static pages that **re-generate in the background** after a `revalidate` window — static speed with fresh-ish data.', 'How do you enable ISR in the App Router?', 'Set `export const revalidate = 60` on the route (seconds), or per-fetch with `next: { revalidate: 60 }`. On-demand: call `revalidatePath()` / `revalidateTag()` after a mutation.', 'intermediate', 'approved', 'core'),
  ('Next.js', '`getStaticProps` vs `getServerSideProps` (Pages Router)?', '- `getStaticProps`: runs at **build time** → a static page (SSG); add `revalidate` for ISR.
- `getServerSideProps`: runs on **every request** on the server (SSR).

Both run only on the server and are stripped from the browser bundle.', 'What replaces them in the App Router?', 'Nothing directly — you fetch inside `async` Server Components. The caching config (`fetch` options, `revalidate`, dynamic APIs) decides static vs dynamic behavior.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What does `next/link` do that a plain `<a>` doesn''t?', '`<Link>` gives **client-side navigation** (no full page reload) and **prefetches** the linked route''s code/data when the link scrolls into view (in production), so navigation feels instant.', 'How do you disable prefetching?', '`<Link prefetch={false}>`. Useful for rarely-clicked links to save bandwidth.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What is `next/image` and why use it?', 'An `<Image>` component with automatic **resizing/optimization**, modern formats (WebP/AVIF), **lazy loading** by default, and reserved space to prevent layout shift.', 'Why does it require `width`/`height` (or `fill`)?', 'To reserve the correct aspect-ratio box before the image loads, avoiding **Cumulative Layout Shift (CLS)**. Use `fill` with a positioned parent when dimensions are unknown.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What are Route Handlers?', 'API endpoints in the App Router — export HTTP-method functions from `app/**/route.js`:

```js
export async function GET(req) {
  return Response.json({ ok: true });
}
```

They replace `pages/api/*`.', 'Are GET Route Handlers cached?', 'In Next 15, **no** — they''re dynamic by default. (Next 14 cached them by default.) Opt into caching with segment config like `export const dynamic = ''force-static''`.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What is Next.js Middleware?', 'Code in `middleware.ts` at the project root that runs **before a request completes**, on the Edge runtime. Used for auth gating, redirects, rewrites, A/B tests, and headers/cookies. A `matcher` config controls which paths it runs on.', 'Why shouldn''t you query your database in middleware?', 'It runs on the **Edge runtime** (limited APIs, must be fast) for every matched request. Do lightweight work (read a token) and defer heavy queries to the route.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What are Server Actions?', 'Async functions marked `"use server"` that run on the server and can be called from forms/components to **mutate data** without a separate API route:

```jsx
async function add(formData) {
  "use server";
  await db.insert(...);
  revalidatePath(''/list'');
}
// <form action={add}>
```', 'How do you refresh the UI after a Server Action mutates data?', 'Call `revalidatePath()`/`revalidateTag()` inside the action (or `redirect()`); the affected Server Components re-render with fresh data.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What''s the role of `layout.js`?', 'It defines shared UI that **wraps** a route segment and its children. Layouts **persist across navigation** — they don''t re-render when you move between sibling pages, preserving state (scroll, inputs). The root layout must render `<html>` and `<body>`.', 'How does `layout.js` differ from `template.js`?', 'A `layout` persists and keeps state between navigations. A `template` creates a **new instance** each navigation (state resets, effects re-run) — good for enter animations or per-page resets.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What do `loading.js` and `error.js` do?', '- `loading.js`: an instant loading UI shown via a **Suspense boundary** while the segment''s data loads (enables streaming).
- `error.js`: an **error boundary** for the segment — catches render errors and shows a fallback with a `reset()` function.', 'Why must `error.js` be a Client Component?', 'Error boundaries rely on React state/lifecycle to catch and recover, which only works client-side — so `error.js` needs `"use client"`.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'How do dynamic routes work in the App Router?', 'Bracketed folder names:
- `[id]` → one dynamic segment (`/post/123`).
- `[...slug]` → catch-all (`/a/b/c`).
- `[[...slug]]` → optional catch-all (also matches the base path).

The values arrive in the `params` prop.', 'How do you pre-render dynamic pages at build time?', 'Export `generateStaticParams()` returning the list of params; Next statically generates one page per entry — the App Router equivalent of `getStaticPaths`.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What is streaming with Suspense in the App Router?', 'Instead of waiting for the whole page, Next **streams** HTML in chunks. Wrap slow parts in `<Suspense fallback={...}>` (or use `loading.js`) so fast content shows immediately while slow data streams in behind it.', 'Which real metric does streaming improve?', '**TTFB / First Contentful Paint** — users see the shell and fast content sooner instead of staring at a blank page until the slowest query resolves.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'How does the Metadata API work?', 'Export metadata from a `layout`/`page`:

```js
export const metadata = { title: ''Home'', description: ''...'' };
```

For dynamic values, export an async `generateMetadata({ params })`. Next injects the `<head>` tags — there''s no `next/head` in the App Router.', 'How do you set a title template across pages?', 'In the root layout: `title: { template: ''%s | MyApp'', default: ''MyApp'' }`. Child pages set just their part and it fills `%s`.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'How do environment variables work in Next.js?', 'Vars in `.env*` are **server-only by default**. To expose one to the browser, prefix it with `NEXT_PUBLIC_` — those are inlined into the client bundle at build time.', 'Is it safe to put an API secret in a `NEXT_PUBLIC_` variable?', 'No — `NEXT_PUBLIC_` values are baked into client JS and visible to everyone. Keep secrets unprefixed (server-only) and use them in Server Components/Actions/Route Handlers.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What causes a hydration error in Next.js?', 'The server-rendered HTML doesn''t match what React produces on the client. Common causes: using `window`/`Date.now()`/`Math.random()` during render, invalid HTML nesting, or a browser extension mutating the DOM.', 'How do you render something only on the client to avoid a mismatch?', 'Gate it behind an effect: set a `mounted` flag in `useEffect` and render the dynamic bit only when `mounted`, or use `next/dynamic` with `{ ssr: false }`.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What''s the difference between `redirect()` and `notFound()`?', 'Server helpers from `next/navigation`:
- `redirect(''/path'')` — stop rendering and send the user elsewhere.
- `notFound()` — stop rendering and show the nearest `not-found.js` (404).

Both throw internally, so code after them doesn''t run.', 'Can you call `redirect()` inside a Server Action or Route Handler?', 'Yes — it''s common after a mutation to send the user to the result page. It works in Server Components, Server Actions, and Route Handlers.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'What are parallel and intercepting routes?', '- **Parallel routes** (`@slot`): render multiple independent pages in one layout at once (e.g. dashboard panels), each with its own loading/error.
- **Intercepting routes** (`(.)`, `(..)`): show a route''s content in the current context — the classic use is opening an item in a **modal** while keeping a shareable URL.', 'Give a real use case for intercepting routes.', 'A modal with its own URL: clicking a thumbnail opens `/photo/1` as a modal over the feed, but visiting `/photo/1` directly (or refreshing) shows the full page.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'Where should data fetching live — Server or Client Components?', 'Prefer **Server Components** (closer to the data, no client waterfall, secrets stay server-side). Use Client Components for interactivity; if they need data, pass it down as props or fetch via Route Handlers.', 'How do you pass server-fetched data into a Client Component?', 'Fetch in the parent Server Component and pass it as **serializable props**. The Client Component receives it already-resolved — no client fetch needed.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'Explain tag-based caching: `revalidateTag` / `revalidatePath`.', 'Tag your fetches: `fetch(url, { next: { tags: [''posts''] } })`. After a write, call `revalidateTag(''posts'')` (or `revalidatePath(''/blog'')`) to purge just that data, so the next request re-fetches while everything else stays cached.', 'Why prefer tag invalidation over time-based `revalidate`?', 'Tags invalidate **exactly** what changed the moment it changes (event-driven), instead of serving stale data until a timer expires. Best when you control the writes.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'How do you do client-side data fetching/mutations in Next.js?', 'For client interactivity, use **SWR** or **React Query** against Route Handlers, or call **Server Actions**. These handle caching, dedup, revalidation, loading, and error states for you.', 'Why is raw `useEffect` + `fetch` discouraged for data?', 'It runs after render (waterfalls), has no caching/dedup, and makes you hand-roll loading/error/refetch. SWR / React Query / Server Components solve those out of the box.', 'intermediate', 'approved', 'core'),
  ('Next.js', 'How does `useRouter` differ between App and Pages routers?', 'Different import and API. App Router: `import { useRouter } from ''next/navigation''` (`push`, `replace`, `refresh`, `back`; no `query`/`pathname`). Pages Router: `import { useRouter } from ''next/router''` (`query`, `pathname`, `asPath`).', 'How do you read the pathname / search params in the App Router?', 'Use the dedicated Client hooks `usePathname()` and `useSearchParams()` from `next/navigation`.', 'intermediate', 'approved', 'core'),
  ('React', 'When should you use `useMemo` vs `useCallback`?', '- `useMemo` memoizes a **computed value** so an expensive calculation doesn''t re-run every render.
- `useCallback` memoizes a **function reference** so it stays stable across renders.

Both exist to avoid wasted work/re-renders — not to sprinkle everywhere.', 'When is `useCallback` actually necessary?', 'When the function is passed to a `memo`-ized child (stable identity prevents its re-render) or used as another hook''s dependency. Otherwise it usually adds overhead for no gain.', 'intermediate', 'approved', 'core'),
  ('React', 'What does `React.memo` do?', 'Wraps a component so it **skips re-rendering** when its props are shallow-equal to last time — memoizing output by props.', 'Why might a `memo` component still re-render every time?', 'If a parent passes a new object/array/function each render (new reference), the shallow compare fails. Stabilize those props with `useMemo`/`useCallback`.', 'intermediate', 'approved', 'core'),
  ('React', '`useEffect` vs `useLayoutEffect`?', 'Both run after render, but `useLayoutEffect` fires **synchronously after DOM mutation, before paint** — use it to measure layout or mutate the DOM without flicker. `useEffect` runs **after paint** (async) and is the default.', 'What''s the downside of `useLayoutEffect`?', 'It blocks painting, so heavy work there hurts perceived performance, and it warns during SSR. Use it only when you must read/write layout before paint.', 'intermediate', 'approved', 'core'),
  ('React', 'What is `useReducer` and when beats `useState`?', 'A hook managing state via a `(state, action) => newState` reducer. Prefer it when state is **complex/interdependent**, when the next state depends on the previous, or when you want centralized, testable update logic.', 'How does `useReducer` help performance?', '`dispatch` has a **stable identity**, so you can pass it down without breaking `memo`/`useCallback` — avoiding the churn of threading many setter callbacks.', 'intermediate', 'approved', 'core'),
  ('React', 'Controlled vs uncontrolled components?', '- **Controlled**: React state is the source of truth (`value` + `onChange`).
- **Uncontrolled**: the DOM holds the value; you read it via a `ref` (or `defaultValue`).

Controlled enables per-keystroke validation/formatting; uncontrolled is simpler and closer to native.', 'What triggers the ''you provided a `value` without `onChange`'' warning?', 'Setting `value` with no `onChange` makes a read-only input. Fix by adding `onChange` (controlled) or using `defaultValue` (uncontrolled).', 'intermediate', 'approved', 'core'),
  ('React', 'What is `useRef` for?', 'A mutable container (`ref.current`) that **persists across renders without triggering one**. Uses: DOM node access, storing timers/previous values, or any mutable instance value that shouldn''t drive the UI.', 'Why not just use a variable or state instead?', 'A local variable resets each render; state re-renders on change. A ref persists and is silent — ideal for values that shouldn''t cause re-renders.', 'intermediate', 'approved', 'core'),
  ('React', 'What is a React Portal?', '`createPortal(children, domNode)` renders children into a **different DOM node** (e.g. `document.body`) while keeping them in the React tree. Great for modals, tooltips, and toasts that must escape parent `overflow`/`z-index`.', 'Do events bubble through a portal to the React parent?', 'Yes — bubbling follows the **React tree**, not the DOM tree. A click inside a portal still reaches its React parent''s handlers.', 'intermediate', 'approved', 'core'),
  ('React', 'What is an Error Boundary?', 'A class component with `getDerivedStateFromError`/`componentDidCatch` that **catches render-time errors** in its subtree and shows a fallback instead of crashing the whole app.', 'What errors do boundaries NOT catch?', 'Errors in event handlers, async code (`setTimeout`, promises), during SSR, and errors thrown in the boundary itself. Handle those with `try/catch`.', 'intermediate', 'approved', 'core'),
  ('React', 'Why does React need `key` props in lists?', 'Keys let React match elements across renders to decide what to reuse, move, or discard. Without stable keys it falls back to index matching and can **attach the wrong state to the wrong item**.', 'Why is the array index a risky key?', 'If the list reorders/inserts/deletes, indexes shift, so React keeps old state on the wrong row — wrong inputs, checkboxes, animations. Use a stable unique id.', 'intermediate', 'approved', 'core'),
  ('React', 'What does StrictMode do in development?', 'A dev-only wrapper that surfaces bugs: it **double-invokes** render, effects (mount→unmount→mount), and state updaters to expose impure renders and missing cleanup. It renders nothing and does nothing in production.', 'My effect runs twice on mount — bug?', 'That''s StrictMode testing your cleanup. Make effects idempotent and clean up (abort fetches, clear subscriptions); the double-run is gone in production.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Explain the event loop: microtasks vs macrotasks.', 'The call stack runs sync code. When empty, the loop drains **all microtasks** (Promise callbacks, `queueMicrotask`) first, then takes **one macrotask** (`setTimeout`, I/O, events), then drains microtasks again, and repeats.', 'What logs first: `setTimeout(fn, 0)` or a resolved `Promise.then`?', 'The Promise. Microtasks run before the next macrotask (`setTimeout`) even with a 0 ms delay.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'How does `this` binding work?', '`this` is set by **how a function is called**:
- `obj.fn()` → `obj`.
- `fn()` → `undefined` (strict) or global.
- `call`/`apply`/`bind` → explicit.
- `new` → the new instance.
- Arrow functions → inherit `this` lexically (no own `this`).', 'Why do arrow functions fix the classic callback `this` bug?', 'They don''t bind their own `this`; they capture it from the enclosing scope, so `this` inside a callback still points at the surrounding object/component.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Deep copy vs shallow copy?', '- **Shallow** (`{...obj}`, `Object.assign`): copies the top level; nested objects stay shared references.
- **Deep**: nested objects are cloned too. Modern deep clone: `structuredClone(obj)`.', 'Pitfalls of `JSON.parse(JSON.stringify(obj))`?', 'It drops `undefined`, functions, and symbols, mangles `Date`/`Map`/`Set` (Dates become strings), and throws on circular refs. `structuredClone` handles most of these.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What is a closure, and a common gotcha?', 'A function that **remembers variables from its lexical scope** even after that scope returned. Gotcha: capturing a loop variable declared with `var` — all the closures share one binding.', 'How does `let` fix the loop-closure bug?', '`let` creates a **fresh binding each iteration**, so every closure captures its own value. `var` has one function-scoped binding shared by all.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`Map` vs plain object for key-value data?', '- `Map`: any key type (objects, functions), preserves insertion order, has `.size`, easy iteration, no prototype collisions.
- `Object`: string/symbol keys, JSON-friendly, best for fixed-shape records.

Reach for `Map` on frequent add/remove or non-string keys.', 'Name a subtle bug from using a plain object as a hash map.', 'Inherited keys: `''toString''`/`''constructor''` collide with prototype members and `''hasOwnProperty'' in obj` is always true. `Map` (or `Object.create(null)`) avoids it.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'Debounce vs throttle?', '- **Debounce**: wait until activity **stops** for N ms, then fire once (search-as-you-type, resize end).
- **Throttle**: fire at most **once per N ms** during continuous activity (scroll, mousemove).

Debounce = ''after the storm''; throttle = ''rate limit''.', 'Which fits a search-input autocomplete?', 'Debounce — hit the API only after the user pauses typing, not on every keystroke.', 'intermediate', 'approved', 'core'),
  ('JavaScript', '`==` vs `===`?', '`===` is strict equality (no coercion). `==` coerces types first, which surprises (`0 == ''''`, `[] == false`, `null == undefined` are all true). Prefer `===`, except the idiomatic `x == null`.', 'What does `x == null` match?', 'Exactly `null` and `undefined` — nothing else. A common shorthand nullish check.', 'intermediate', 'approved', 'core'),
  ('JavaScript', 'What are `async`/`await` really doing?', '`async` makes a function return a Promise; `await` pauses it until a Promise settles, resuming with the value — asynchronous code written in a synchronous style. Errors surface through `try/catch`.', 'How do you run independent awaits concurrently instead of in series?', 'Start them, then await together: `await Promise.all([a(), b()])`. Writing `await a(); await b();` runs them one after the other.', 'intermediate', 'approved', 'core'),
  ('TypeScript', '`unknown` vs `any`?', '- `any` disables type checking — anything goes (unsafe).
- `unknown` is the **type-safe** top type: you can assign anything to it, but must **narrow** it (typeof/instanceof/guards) before use.

Prefer `unknown` at boundaries (`catch`, parsed JSON).', 'What''s the default type of a `catch` variable in modern TS?', '`unknown` (with `useUnknownInCatchVariables`). You must narrow it before touching `.message`.', 'intermediate', 'approved', 'core'),
  ('TypeScript', '`type` vs `interface`?', 'Both describe object shapes. `interface` supports **declaration merging** and reads well for public object/class contracts. `type` is more flexible: unions, intersections, tuples, mapped/conditional types, primitive aliases.', 'Which can represent a union like `''a'' | ''b''`?', 'Only `type` — `type Status = ''a'' | ''b''`. An interface can''t be a union.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'Explain generics with an example.', 'Type parameters that let code work over many types while keeping their relationship:

```ts
function first<T>(arr: T[]): T | undefined {
  return arr[0];
}
first([1, 2]); // T = number
```

The return type tracks the input type.', 'How do you constrain a generic to types that have `.length`?', '`<T extends { length: number }>`. Now only types with a numeric `length` are accepted, and `.length` is typed inside.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What do `Partial`, `Pick`, `Omit`, and `Record` do?', '- `Partial<T>` — all props optional.
- `Pick<T, K>` — keep only keys `K`.
- `Omit<T, K>` — drop keys `K`.
- `Record<K, V>` — object type with keys `K`, values `V`.

They derive new types instead of duplicating.', 'How would you type an object mapping user ids to `User`?', '`Record<string, User>` (or `Record<UserId, User>` with a branded id type).', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What is a discriminated union?', 'A union of object types sharing a **literal discriminant** field so TS can narrow:

```ts
type Shape =
  | { kind: ''circle''; r: number }
  | { kind: ''square''; s: number };
```

`switch (shape.kind)` narrows each branch.', 'How do you make TS enforce every variant is handled?', 'In the `default`, assign to `const _x: never = shape`. Add a new variant and it becomes a compile error — an exhaustiveness check.', 'intermediate', 'approved', 'core'),
  ('TypeScript', '`enum` vs an `as const` object?', '`enum` emits runtime code and has quirks (numeric enums are reverse-mapped, not tree-shakeable). A `const` object + `as const` is a plain, tree-shakeable value with a literal union type derived via `typeof`/`keyof`.', 'How do you derive a union from a `const` object''s values?', '```ts
const Roles = { admin: ''admin'', user: ''user'' } as const;
type Role = typeof Roles[keyof typeof Roles];
```', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What does the `satisfies` operator do?', 'It checks a value **conforms to** a type **without widening** its inferred type, so you keep precise literal types while validating the shape:

```ts
const cfg = { port: 3000 } satisfies Config;
```

`cfg.port` stays a narrow `number`, and mismatches error.', 'How is `satisfies` different from a `: Type` annotation?', 'An annotation widens the variable to that type (losing literal precision). `satisfies` validates but preserves the narrower inferred type.', 'intermediate', 'approved', 'core'),
  ('TypeScript', 'What are `keyof` and `typeof` in a type context?', '- `typeof x` (in type position) gets the **type** of a runtime value.
- `keyof T` produces a union of `T`''s **keys**.

Together, `keyof typeof obj` gives the literal union of an object''s keys.', 'How do you type `get(obj, key)` so it returns the right value type?', '```ts
function get<T, K extends keyof T>(o: T, k: K): T[K] {
  return o[k];
}
```

`T[K]` is an indexed access type.', 'intermediate', 'approved', 'core'),
  ('CSS', 'How does CSS specificity work?', 'Scored as (inline, ids, classes/attrs/pseudo-classes, elements): inline > `#id` (100) > `.class`/`[attr]`/`:hover` (10) > element/`::pseudo-element` (1). Higher score wins; on a tie, the **last** rule wins.', 'Where does `!important` fit, and why avoid it?', '`!important` overrides normal specificity entirely. Avoid it because it starts wars — the only way to beat one is another `!important`, which snowballs.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What creates a stacking context, and why does `z-index` sometimes ''not work''?', 'A stacking context is a self-contained layer; `z-index` only compares **siblings within the same context**. `position`+`z-index`, `opacity < 1`, `transform`, `filter`, and `will-change` all create new contexts.', 'Why can a `z-index: 9999` element still sit behind another?', 'Because its **parent** formed a stacking context with a lower z-index. A child can''t escape its parent''s layer, no matter how high its own z-index.', 'intermediate', 'approved', 'core'),
  ('CSS', 'Flexbox vs Grid — when to use which?', '- **Flexbox**: one-dimensional (a row or a column) — toolbars, nav, distributing space along one axis.
- **Grid**: two-dimensional (rows and columns together) — page layouts, card galleries.

They compose: grid for the macro layout, flex inside cells.', 'How do you center a box both ways with each?', 'Flex: `display:flex; justify-content:center; align-items:center`. Grid: `display:grid; place-items:center`.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What are container queries vs media queries?', 'Container queries style an element based on the size of its **containing element** (`container-type: inline-size` + `@container (min-width: ...)`), not the viewport — so components adapt to whatever slot they sit in.', 'Why are they better than media queries for component libraries?', 'A media query only knows the viewport, so a card can''t tell a narrow sidebar from a wide main area. A container query lets the card respond to **its own space**.', 'intermediate', 'approved', 'core'),
  ('CSS', 'What do `min()`, `max()`, and `clamp()` do?', 'Math functions for responsive values without media queries:
- `min(a, b)` — the smaller.
- `max(a, b)` — the larger.
- `clamp(min, preferred, max)` — preferred, bounded.

E.g. `font-size: clamp(1rem, 2vw + 1rem, 2rem)` for fluid type.', 'Why is `width: min(100%, 40rem)` a handy container pattern?', 'It''s `40rem` on wide screens but shrinks to `100%` on small ones — a responsive max-width with no media query.', 'intermediate', 'approved', 'core'),
  ('CSS', '`relative` vs `absolute` vs `fixed` vs `sticky` positioning?', '- `relative`: offset from its normal spot; keeps its space; becomes a positioning context.
- `absolute`: removed from flow, positioned to the nearest positioned ancestor.
- `fixed`: positioned to the viewport, stays on scroll.
- `sticky`: relative until it hits a threshold, then sticks.', 'Why is my `sticky` element not sticking?', 'Usual causes: no threshold set (e.g. `top: 0`), an ancestor with `overflow: hidden/auto`, or the parent isn''t tall enough to scroll within.', 'intermediate', 'approved', 'core'),
  ('HTML', 'Why associate a `<label>` with an input?', 'It ties a caption to a control so screen readers announce it, and clicking the label focuses/activates the input (a bigger hit target). Use `<label for="id">` or wrap the input inside the label.', '`for`/`id` vs wrapping — any difference?', 'Both work. Explicit `for`/`id` is more robust in deeply nested markup; wrapping needs no ids but the control must sit inside the label.', 'intermediate', 'approved', 'core'),
  ('HTML', '`async` vs `defer` on a `<script>`?', '- `async`: download in parallel, **execute as soon as ready** (order not guaranteed) — for independent scripts like analytics.
- `defer`: download in parallel, **execute in order after HTML parses**, before `DOMContentLoaded` — for app scripts needing the DOM.', 'What does a plain `<script>` in `<head>` do to load time?', 'It **blocks HTML parsing** while downloading and executing, delaying render — which is why scripts go at the end of `<body>` or use `defer`.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What does the viewport meta tag do?', '`<meta name="viewport" content="width=device-width, initial-scale=1">` tells mobile browsers to use the real device width instead of a fake ~980px desktop width, so responsive CSS works. Without it, mobile pages render zoomed out.', 'Why avoid `user-scalable=no`?', 'It blocks pinch-zoom — an accessibility failure for low-vision users. Let people zoom.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What is ARIA, and what''s the first rule of ARIA?', 'ARIA attributes (`role`, `aria-label`, `aria-expanded`…) add semantics for assistive tech when native HTML can''t express them. **First rule: don''t use ARIA** if a native element (`<button>`, `<nav>`) already conveys it.', 'Why is a native `<button>` better than `<div role="button">`?', 'The native button gives focusability, keyboard activation (Enter/Space), and semantics for free. The div needs `tabindex`, key handlers, and `role` — easy to get wrong.', 'intermediate', 'approved', 'core'),
  ('HTML', 'What does the `<iframe sandbox>` attribute do?', 'It restricts embedded content. With an empty `sandbox` the iframe can''t run scripts, submit forms, reach its parent, or navigate the top window. You re-grant capabilities selectively (`allow-scripts`, `allow-forms`, …).', 'Why is `sandbox="allow-scripts allow-same-origin"` together risky?', 'Granting both lets the framed content run scripts **and** access its own origin, so same-origin content can strip its own sandbox attribute — defeating the isolation.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is the Critical Rendering Path?', 'The steps to turn bytes into pixels: parse HTML→DOM, parse CSS→CSSOM, combine into the render tree, layout (geometry), then paint. Render-blocking CSS/JS stalls it and delays first paint.', 'Why is CSS render-blocking by default?', 'The browser won''t paint until it has the CSSOM, to avoid a flash of unstyled content. Inline critical CSS and defer the rest to unblock paint.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is code splitting, and how in React?', 'Breaking the bundle into chunks loaded on demand so users don''t download the whole app upfront. In React: `const X = lazy(() => import(''./X''))` inside a `<Suspense>` boundary; route-level splitting is the biggest win.', 'What''s the risk of over-splitting?', 'Too many tiny chunks add request overhead and can cause loading waterfalls/jank. Split at meaningful boundaries (routes, heavy widgets), not every component.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What are the Core Web Vitals?', '- **LCP** (Largest Contentful Paint) — loading; target < 2.5s.
- **CLS** (Cumulative Layout Shift) — visual stability; < 0.1.
- **INP** (Interaction to Next Paint) — responsiveness; < 200ms (replaced FID in 2024).', 'What commonly hurts CLS?', 'Images/ads/iframes without reserved dimensions, and web fonts causing reflow. Set width/height (or `aspect-ratio`) and tune `font-display`.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is tree shaking?', 'Dead-code elimination that drops unused exports from the bundle, relying on **ES module** static `import`/`export` analysis. The bundler keeps only what''s actually imported.', 'Why can `import * as _ from ''lodash''` defeat tree shaking?', 'Whole-namespace / CommonJS imports aren''t statically analyzable per-function. Use `lodash-es` with named imports (or `lodash/get`) so only used functions ship.', 'intermediate', 'approved', 'core'),
  ('Performance', 'How does browser caching improve performance?', 'Cached assets skip the network entirely. `Cache-Control` governs it: a long `max-age` plus **content-hashed filenames** (`app.abc123.js`) means files cache ''forever'' and a new deploy just changes the hash (cache-busting).', 'Why hash filenames instead of a short max-age?', 'Hashing lets you cache immutably for a year AND update instantly — the URL changes when content changes. A short max-age forces slow revalidation every visit.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What is lazy loading, and how do you lazy-load images?', 'Deferring off-screen resources until needed. For images: `<img loading="lazy">` (native) or an IntersectionObserver. It saves bandwidth and speeds the initial load.', 'Should you lazy-load the LCP/hero image?', 'No — lazy-loading the above-the-fold hero **delays** LCP. Eager-load it (even `fetchpriority="high"`) and lazy-load only below-the-fold images.', 'intermediate', 'approved', 'core'),
  ('Performance', 'What causes memory leaks in a SPA, and how do you prevent them?', 'Holding references that are never released: uncleared timers/intervals, un-removed event listeners, live subscriptions, or detached DOM kept alive in closures. Over a long session memory grows and the app janks.', 'How do you prevent leaks in a React effect?', 'Return a cleanup function that clears timers, removes listeners, aborts fetches, and unsubscribes — React runs it on unmount and before re-running the effect.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What''s the core idea — and tradeoff — of utility-first CSS?', 'Compose styles from small single-purpose classes (`flex`, `pt-4`, `text-sm`) in markup instead of writing custom CSS. Pros: no naming, no dead CSS, a consistent scale, fast iteration. Con: verbose class lists mixing structure with styling.', 'How do you avoid repeating the same long class list everywhere?', 'Extract a **component** (in React) that owns the classes — the idiomatic answer — rather than `@apply`, which recreates the abstraction problems of custom CSS.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How do responsive styles work in Tailwind?', 'Prefixes are **min-width** breakpoints, applied mobile-first: unprefixed = all sizes, then `sm: md: lg: xl: 2xl:` apply from that width up. `text-sm md:text-base` = small by default, larger from `md`.', 'Does `md:flex` mean ''only on medium screens''?', 'No — it means ''from `md` **and up**'' (min-width), so it also applies at lg and xl. Use `max-*` variants for a range that''s only medium.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How does dark mode work in Tailwind?', 'Prefix utilities with `dark:` (e.g. `bg-white dark:bg-gray-900`). It activates via OS preference (`media` strategy) or a `.dark` class on a parent (`class`/`selector` strategy) that you toggle in JS.', 'Why pick the `class` strategy over `media`?', 'It lets users choose a theme manually (and persist it), independent of the OS setting — you toggle a `dark` class on `<html>`.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'What does `@apply` do, and when should you avoid it?', '`@apply` inlines utility classes into a custom CSS rule (`.btn { @apply px-4 py-2 rounded; }`). Use it sparingly — small primitives, third-party overrides. Overusing it rebuilds the semantic-CSS problems Tailwind set out to avoid.', 'What''s the preferred alternative in a React app?', 'A component that encapsulates the utilities (`<Button>`), so the abstraction lives in one place and stays composable.', 'intermediate', 'approved', 'core'),
  ('Tailwind', 'How does Tailwind keep the CSS bundle small?', 'It scans your source files (the `content` globs) and generates **only the classes you actually use**. Unused utilities never reach production CSS, so the bundle stays tiny no matter how many utilities exist.', 'Why can dynamic class names like `` `text-${color}-500` `` break in production?', 'The scanner reads class strings **statically** — it can''t evaluate template literals, so those classes get purged. Use complete literal class names or a safelist.', 'intermediate', 'approved', 'core');
